import numpy as np
def _fx_midpoint_mesh(z_min, z_max, n_bins):
    n = int(n_bins)
    edges = np.linspace(float(z_min), float(z_max), n + 1)
    mids = 0.5 * (edges[:-1] + edges[1:])
    widths = np.full(n, (float(z_max) - float(z_min)) / n)
    return np.vstack([mids, widths])
def _fx_length_to_weight(lengths, intercept=1.02, slope=3.02):
    zz = np.asarray(lengths, dtype=np.float64)
    return 10.0 ** (float(intercept) + float(slope) * np.log10(zz))
def _fx_survival_probability(lengths, slope=2.7, exponent=-0.315):
    zz = np.asarray(lengths, dtype=np.float64)
    grams = 1000.0 * _fx_length_to_weight(zz)
    return np.exp(-float(slope) * grams ** float(exponent))
def _fx_maturity_probability(lengths, intercept=-7.41, slope=24.98):
    zz = np.asarray(lengths, dtype=np.float64)
    return 1.0 / (1.0 + np.exp(-(float(intercept) + float(slope) * zz)))
def _fx_growth_kernel(midpoints, width, mu0=0.194, mu1=0.841, sd=0.1):
    zz = np.asarray(midpoints, dtype=np.float64)
    mean = float(mu0) + float(mu1) * zz[None, :]
    pdf = np.exp(-0.5 * ((zz[:, None] - mean) / float(sd)) ** 2) / (float(sd) * np.sqrt(2.0 * np.pi))
    return pdf * float(width)
def _fx_recruit_length_density(midpoints, mean=0.319, sd=0.040):
    zz = np.asarray(midpoints, dtype=np.float64)
    return np.exp(-0.5 * ((zz - float(mean)) / float(sd)) ** 2) / (float(sd) * np.sqrt(2.0 * np.pi))
def _fx_ricker_allee_target(biomass, gamma, allee_threshold, carrying_capacity):
    b, g, C, K = float(biomass), float(gamma), float(allee_threshold), float(carrying_capacity)
    return b * np.exp(g * (1.0 - b / K) * ((b - C) / K))
mesh = _fx_midpoint_mesh(0.01, 1.5, 300)
z, w = mesh[0], mesh[1]
weights = _fx_length_to_weight(z)
survival = _fx_survival_probability(z)
maturity = _fx_maturity_probability(z)
growth = _fx_growth_kernel(z, float(w[0]))
recruit_density = _fx_recruit_length_density(z, 0.319, 0.040)
w_adult = float(_fx_length_to_weight(np.array([0.867]))[0])
recruits_per_spawner = 2
density = 800.0 * np.exp(-0.5 * ((z - 0.300) / 0.020) ** 2) / (0.020 * np.sqrt(2.0 * np.pi))
target_biomass = _fx_ricker_allee_target(float(np.sum(weights * density * w)), 1.837, 10.0 * w_adult, 500.0 * w_adult)
assert np.allclose(spawning_proportion(density, mesh, growth, survival, weights, maturity, recruit_density, recruits_per_spawner, target_biomass), target)

